import React from 'react';
import { Panel, ScreenSpinner, Div, Button, Text } from '@vkontakte/vkui';
import { BaseScaffold } from '../components/ui/BaseScaffold';
import { UserCard } from '../components/profile/UserCard';
import { AddressesSection } from '../components/profile/AddressesSection';
import { useUserProfile } from '../hooks/useUserProfile';

export const ProfileScreen: React.FC = () => {
  const {
    user,
    addresses,
    loading,
    // saving,
    error,
    // updatePhone,
    addAddress,
    deleteAddress,
    getVKPhone,
  } = useUserProfile();

  if (loading) {
    return (
      <Panel id="profile">
        <ScreenSpinner />
      </Panel>
    );
  }

  if (error) {
    return (
      <Panel id="profile">
        <Div style={{ textAlign: 'center', padding: '20px' }}>
          <Text>Ошибка: {error}</Text>
          <Button onClick={() => window.location.reload()}>
            Попробовать снова
          </Button>
        </Div>
      </Panel>
    );
  }

  if (!user) {
    return (
      <Panel id="profile">
        <Div style={{ textAlign: 'center', padding: '20px' }}>
          <Text>Пользователь не найден</Text>
        </Div>
      </Panel>
    );
  }

  return (
    <Panel id="profile">
      <BaseScaffold>
        <div style={{ padding: '16px' }}>
          <UserCard
            user={user}
            // onPhoneUpdate={getVKPhone}
            onGetVKPhone={getVKPhone}
          />
          
          <AddressesSection
            addresses={addresses}
            onAddAddress={addAddress}
            onDeleteAddress={deleteAddress}
            loading={loading}
          />
        </div>
      </BaseScaffold>
    </Panel>
  );
};