import React from "react";
import { BaseScaffold } from "../components/ui/BaseScaffold";
import { MainHeader } from "../components/layout/MainHeader";
import { MenuButton } from "../components/ui/MenuButton";
import { MenuItem } from "../types";

export const MainMenu: React.FC = () => {
  const menuItems: MenuItem[] = [
    {
      id: "profile",
      icon: "👤",
      title: "Профиль",
      subtitle: "Управление профилем",
      panel: "profile", // Добавляем переход на панель профиля
    },
    {
      id: "schedule",
      icon: "📅",
      title: "Расписание вывоза",
      subtitle: "График вывоза мусора",
      action: () => console.log("Navigate to schedule"),
    },
    {
      id: "locations",
      icon: "📍",
      title: "Пункты приема",
      subtitle: "Карта пунктов приема",
      action: () => console.log("Navigate to locations"),
    },
    {
      id: "requests",
      icon: "📋",
      title: "Мои заявки",
      subtitle: "История заявок",
      action: () => console.log("Navigate to requests"),
    },
    {
      id: "work",
      icon: "💼",
      title: "Работать",
      subtitle: "Начать работу",
      action: () => console.log("Navigate to work"),
    },
    {
      id: "about",
      icon: "ℹ️",
      title: "О приложении",
      subtitle: "Информация о сервисе",
      action: () => console.log("Navigate to about"),
    },
  ];

  return (
    <BaseScaffold
      header={<MainHeader title="Вынос мусора" subtitle="Экологичный сервис" />}
    >
      <div
        style={{
          padding: "24px",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column" as const,
            gap: "16px",
            marginBottom: "32px",
          }}
        >
          {menuItems.map((item) => (
            <MenuButton
              key={item.id}
              icon={item.icon}
              title={item.title}
              subtitle={item.subtitle}
              onClick={item.action!}
            />
          ))}
        </div>
      </div>
    </BaseScaffold>
  );
};
